namespace ETutor.Application.Abstractions;

/// <summary>
/// Where uploaded file bytes live (local disk in development; blob storage later). Keys are generated by the
/// storage, never derived from user input, so a file name can't be used for path traversal.
/// </summary>
public interface IFileStorage
{
    /// <summary>Short provider name stored with each file (e.g. "local").</summary>
    string ProviderName { get; }

    /// <summary>Saves the stream under a new random key and returns that key.</summary>
    Task<string> SaveAsync(Stream content, string extension, CancellationToken cancellationToken);

    Task<Stream> OpenReadAsync(string key, CancellationToken cancellationToken);

    Task DeleteAsync(string key, CancellationToken cancellationToken);
}

/// <summary>Recognizes provider-specific database errors without leaking provider types into use cases.</summary>
public interface IDatabaseErrors
{
    /// <summary>True when <paramref name="exception"/> is a unique-index or primary-key violation.</summary>
    bool IsUniqueViolation(Exception exception);
}
